CustomField.formula:
if ( isblank(Tuesday_Time_In__c) && isblank (Tuesday_Time_Out__c), 0,

if ( isblank(Tuesday_Lunch_End__c) && isblank(Tuesday_Lunch_Start__c),

( 

(floor(Tuesday_Time_Out_Proxy__c) + (Tuesday_Time_Out_Proxy__c- floor(Tuesday_Time_Out_Proxy__c))/60*100)

- (floor(Tuesday_Time_In_Proxy__c) + (Tuesday_Time_In_Proxy__c- floor(Tuesday_Time_In_Proxy__c))/60*100)

),

( 

(floor(Tuesday_Lunch_Start_Proxy__c ) + (Tuesday_Lunch_Start_Proxy__c - floor(Tuesday_Lunch_Start_Proxy__c ))/60*100)

- (floor(Tuesday_Time_In_Proxy__c) + (Tuesday_Time_In_Proxy__c- floor(Tuesday_Time_In_Proxy__c))/60*100)

)

))
